evidence.answerQuery:
PREFIX agents: <https://data.oireachtas.ie/ontology#>
PREFIX dcat: <http://www.w3.org/ns/dcat#>
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX eli: <http://data.europa.eu/eli/ontology#>
PREFIX eli-dl: <http://data.europa.eu/eli/eli-draft-legislation-ontology#>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
PREFIX members: <https://data.oireachtas.ie/ontology/members#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT DISTINCT ?bill ?title ?year ?process ?number ?status ?eventDate ?eventType ?memoWork ?memo WHERE { GRAPH <https://data.oireachtas.ie/graph/bill/2020/11> {
          <https://data.oireachtas.ie/ie/oireachtas/bill/2020/11> a eli-dl:DraftLegislationWork ; eli:work_type agents:Bill .
          BIND(<https://data.oireachtas.ie/ie/oireachtas/bill/2020/11> AS ?bill)
          OPTIONAL { <https://data.oireachtas.ie/ie/oireachtas/bill/2020/11> dct:title ?title . FILTER(LANG(?title) = "en") }
          OPTIONAL { <https://data.oireachtas.ie/ie/oireachtas/bill/2020/11> agents:legislativeYear ?year }
          OPTIONAL { ?delivery a agents:BillDelivery ; eli-dl:created_a_realization_of ?bill ; eli-dl:forms_part_of ?process .
            ?process a eli-dl:LegislativeProcess . OPTIONAL { ?process eli-dl:process_number ?number } OPTIONAL { ?process eli-dl:process_status ?status }
            OPTIONAL { ?activity a eli-dl:LegislativeActivity ; eli-dl:forms_part_of ?process ; eli-dl:activity_date ?eventDate ; eli-dl:had_activity_type ?eventType . FILTER(DATATYPE(?eventDate) = xsd:date) } }
          OPTIONAL { <https://data.oireachtas.ie/ie/oireachtas/bill/2020/11> eli:has_part ?memoWork . ?memoWork a eli:Work ; eli:type_document agents:ExplanatoryMemo .
            OPTIONAL { ?memoWork eli:is_realized_by ?memoExpression . ?memoExpression a eli:LegalExpression ; eli:is_embodied_by ?memoFormat . ?memoFormat a eli:Format ; eli:uri_schema ?memo } }
        } } LIMIT 100

